 const currentJobs=new Map(),jobQuote=new Map(),jobInvoice=new Map(),jobPaid=new Map(),invoiceGroups=new Map(),invoicePaid=new Map();
 const sum=(map,key,n)=>map.set(key,(map.get(key)||0n)+n);
