  for(const r of rows)revisions.push({...clean(r),sourceLine:r._line,sourceEndLine:r._endLine,selected:!!selected&&r.revision_id===selected.revision_id,future:r._time>day.asOf});
  if(!selected)continue;currentJobs.set(selected.job_id,selected);
